class WordFilter {
    struct TrieNode {
        TrieNode* children[27];
        int weight;
        TrieNode() {
            for (int i = 0; i < 27; i++) children[i] = nullptr;
            weight = -1;
        }
    };

    TrieNode* root;

    void insert(const string& s, int w) {
        TrieNode* node = root;
        for (char c : s) {
            int idx = c - 'a';
            if (!node->children[idx]) {
                node->children[idx] = new TrieNode();
            }
            node = node->children[idx];
            if (w > node->weight) {
                node->weight = w;
            }
        }
    }

public:
    WordFilter(vector<string>& words) {
        root = new TrieNode();
        for (int i = 0; i < (int)words.size(); i++) {
            string w = words[i];
            for (int j = 0; j <= (int)w.size(); j++) {
                string s = w.substr(j) + "{" + w;
                insert(s, i);
            }
        }
    }

    int f(string pref, string suff) {
        string key = suff + "{" + pref;
        TrieNode* node = root;
        for (char c : key) {
            int idx = c - 'a';
            if (!node->children[idx]) return -1;
            node = node->children[idx];
        }
        return node->weight;
    }
};
